#!/usr/bin/env python3
"""Generate Codex discovery/transport files; the procedures stay in .claude.

--check is read-only and fails if generated files drift or a source skill disappears.
No symlinks, external packages, personal paths, or server access are required.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re
import sys
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[1]
MARKER = 'Generated by scripts/sync-codex.py'


def metadata(source):
    text = source.read_text(encoding='utf-8-sig')
    if not text.startswith('---\n'):
        raise ValueError(f'No frontmatter: {source}')
    head = text.split('---', 2)[1]
    name = re.search(r'^name:\s*([a-z0-9-]+)\s*$', head, re.M)
    description = re.search(r'^description:\s*(.*)$', head, re.M)
    if not name or not description:
        raise ValueError(f'Missing name/description: {source}')
    if name[1] != source.parent.name:
        raise ValueError(f'Skill name differs from folder: {source}')
    desc = description[1].strip()
    if desc in ('|', '>'):
        tail = head[description.end():]
        lines = []
        for line in tail.splitlines():
            if line and not line[0].isspace():
                break
            if line.strip():
                lines.append(line.strip())
        desc = ' '.join(lines)
    # Keep the actual capability first; detailed triggers remain in the canonical source.
    desc = desc.split('Триггеры:', 1)[0].split('НЕ для', 1)[0].strip()
    if len(desc) > 260:
        cutoff = desc.rfind(' ', 0, 260)
        desc = desc[:cutoff].rstrip(' ,;:') + '.'
    explicit = bool(re.search(r'^disable-model-invocation:[ \t]*true(?:[ \t]+#[^\n]*)?[ \t]*$', head, re.M))
    digest = hashlib.sha256(text.replace('\r', '').encode()).hexdigest()
    return name[1], desc, explicit, digest


def artifacts(root=ROOT):
    files = {}
    for source in sorted((root / '.claude/skills').glob('*/SKILL.md')):
        name, description, explicit, digest = metadata(source)
        canonical = f'.claude/skills/{name}/SKILL.md'
        wrapper = f'''---
name: {name}
description: {json.dumps(description, ensure_ascii=False)}
---

<!-- {MARKER}; source-sha256: {digest} -->

Прочитай [переходник среды](../../../docs/agent-runtimes.md), затем
[каноническую процедуру](../../../{canonical}) **целиком**.
Выполни её в рамках текущей задачи и уже полученной авторизации оператора.
Ресурсы и относительные пути бери из канонической папки `.claude/skills/{name}/`.
Подстановки `!` в исходном Markdown в Codex выполняются явно; не выдавай их текст
за результат команды. Не дублируй и не редактируй процедуру в этой точке входа.
'''
        if explicit:
            wrapper += '\nЭтот навык запускает оператор явно; по одному совпадению описания его не запускай.\n'
        files[f'.agents/skills/{name}/SKILL.md'] = wrapper
        files[f'.agents/skills/{name}/agents/openai.yaml'] = (
            f'# {MARKER}\npolicy:\n  allow_implicit_invocation: {str(not explicit).lower()}\n')
    if not files:
        raise ValueError('No canonical skills found')
    config = f'''# {MARKER}. Personal permissions/provider settings belong in user config.
[features]
hooks = true

[agents]
enabled = true
'''
    files['.codex/config.toml'] = config
    files['.codex/agents/sysadmin.toml'] = f'''# {MARKER}
name = "sysadmin"
description = "Сисадмин персональной инфраструктуры: диагностика, SSH, Docker, VPN, бэкапы и мониторинг по общим правилам проекта."
developer_instructions = """
Прочитай CLAUDE.md корня sysadmin целиком, затем docs/agent-runtimes.md.
Это роль Sysadmin Agent; не вызывай Claude Code вместо выполнения задачи.
Пройди cold-start из .claude/agents/references/cold-start.md, выбери канонический
навык .claude/skills/<имя>/SKILL.md. Соблюдай зоны SSH, подтверждения оператора,
запрет на вывод секретов и обновление inventory после серверных изменений.
При правке мозга переходи в dev и не подключайся к серверам. Наследуй модель,
ограничения и полномочия текущей сессии. Результат опирай на реальные проверки;
недоступную проверку называй явно. Подтверждение из задания субагенту не заменяет
прямую реплику оператора в основной сессии.
"""
'''
    hooks = {'description': MARKER + ': transport for shared Sysadmin guards', 'hooks': {}}
    for event, matcher, hook, status in (
        ('PreToolUse', '(^|\\.)(Bash|exec_command|exec|write_stdin)$', 'red-zone', 'Проверяю зону операции…'),
        ('PreToolUse', '(^|\\.)(apply_patch|Write|Edit)$', 'retro', 'Проверяю основание находки…'),
        ('Stop', None, 'inventory', 'Сверяю inventory с изменениями…')):
        posix = f'sh "$(git rev-parse --show-toplevel)/scripts/runtime/run-hook.sh" {hook}'
        # The PowerShell runner path is resolved at invocation, so clones remain portable.
        # Windows PowerShell 5.1 decodes native output with the OEM code page: a non-ASCII
        # repository path from git (e.g. Cyrillic user name) came back garbled and the hook
        # never started (2026-10-13). Decode git output as UTF-8 explicitly.
        win = ('powershell.exe -NoProfile -ExecutionPolicy Bypass -Command "'
               '[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false); '
               '$taskRoot = git rev-parse --show-toplevel; '
               f'& (Join-Path $taskRoot \'scripts/runtime/run-hook.ps1\') -Hook \'{hook}\'"')
        entry = {'hooks': [{'type': 'command', 'command': posix, 'commandWindows': win,
                            'timeout': 30, 'statusMessage': status}]}
        if matcher:
            entry['matcher'] = matcher
        hooks['hooks'].setdefault(event, []).append(entry)
    files['.codex/hooks.json'] = json.dumps(hooks, ensure_ascii=False, indent=2) + '\n'
    return files


def sync(root, check=False):
    expected = artifacts(root)
    drift = []
    for relative, content in expected.items():
        path = root / relative
        if path.is_symlink():
            raise ValueError(f'Refusing symlink: {relative}')
        current = path.read_text(encoding='utf-8') if path.is_file() else None
        if current != content:
            drift.append(relative)
            if not check:
                if current is not None and MARKER not in current:
                    raise ValueError(f'Refusing to overwrite a hand-written file: {relative}')
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding='utf-8', newline='\n')
    # Report obsolete generated skills instead of deleting user work automatically.
    for path in (root / '.agents/skills').glob('*/SKILL.md'):
        relative = path.relative_to(root).as_posix()
        if relative not in expected:
            drift.append('obsolete: ' + relative)
    return drift


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--staged', action='store_true', help='check the Git index, not the working tree')
    args = parser.parse_args()
    try:
        if args.staged:
            if not args.check:
                parser.error('--staged requires --check')
            drift = check_index()
        else:
            drift = sync(ROOT, args.check)
    except (ValueError, OSError, subprocess.SubprocessError) as error:
        sys.exit(str(error))
    if args.check and drift:
        print('Codex entrypoints are out of sync:\n' + '\n'.join(drift))
        return 1
    print(f'Codex entrypoints: {len(artifacts())} files, ' + ('PASS' if args.check else 'synchronized'))
    return 0


def check_index(root=ROOT):
    """Materialize only relevant index files; unstaged repairs cannot mask a bad commit."""
    result = subprocess.run(['git', '-C', str(root), 'ls-files', '-z', '--',
                             '.claude/skills/*/SKILL.md', '.agents/skills/', '.codex/'],
                            check=True, capture_output=True)
    with tempfile.TemporaryDirectory(prefix='sysadmin-codex-index-') as folder:
        snapshot = Path(folder).resolve()
        for relative in result.stdout.decode('utf-8').split('\0'):
            if not relative:
                continue
            destination = snapshot / relative
            if not destination.resolve().is_relative_to(snapshot):
                raise ValueError('Index path escapes snapshot')
            content = subprocess.run(['git', '-C', str(root), 'show', ':' + relative],
                                     check=True, capture_output=True).stdout
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(content)
        return sync(snapshot, check=True)


if __name__ == '__main__':
    raise SystemExit(main())
